#!/usr/bin/env bash
driver_dir(){ printf '%s/drivers/%s' "$TF_ROOT" "$1"; }; load_driver(){ local d=$1 base; base=$(driver_dir "$d"); [[ -f $base/driver.sh ]]||die "unknown stable driver: $d"; source "$base/driver.sh"; }; list_stable_drivers(){ find "$TF_ROOT/drivers" -mindepth 2 -maxdepth 2 -name driver.toml -print|sort|while read -r f; do awk -F= '/^(id|name|category|lab_user_verified)=/{gsub(/[ \"]/,"",$2);printf "%s=%s ",$1,$2}END{print ""}' "$f"; done; }; list_experimental_drivers(){ find "$TF_ROOT/experimental" -mindepth 2 -maxdepth 2 -name driver.toml -print|sort|while read -r f; do awk -F= '/^(id|name|last_lab_result)=/{gsub(/[ \"]/,"",$2);printf "%s=%s ",$1,$2}END{print ""}' "$f"; done; }
